#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using LastRail.Auth;
using LastRail.Run;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public sealed class BScoutGunnerSourceTests {
  internal static JObject Supplier()=>JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CommanderS1-20260922/combat-b-scout-gunner-source-traces-20261003.json"));
  internal static JObject Packet()=>(JObject)Supplier()["traces"].Single(t=>(string)t["name"]=="actual-signed-definition-only")["body"].DeepClone();
  internal static JObject Sample(int index)=>(JObject)Supplier()["syntheticSourceSamples"][index].DeepClone();
  internal static JObject Trust(JObject p)=>new JObject{["origin"]=Sample(0)["origin"].DeepClone(),["nativeContextId"]=Sample(0)["nativeContextId"].DeepClone(),["seedHash"]=Sample(0)["seedHash"].DeepClone(),["sourceHash"]=p["sourceHash"].DeepClone(),["nodeId"]=p["nodeId"].DeepClone(),["visitDepth"]=p["visitDepth"].DeepClone(),["priorSourceHash"]=p["priorSourceHash"].DeepClone()};
  [Test] public void ActualApprovedDefinitionIsImmutableWithoutRuntimeAuthority(){var type=typeof(RunWaveManifestSnapshot).Assembly.GetType("LastRail.Run.BScoutGunnerDefinitionSnapshot");Assert.NotNull(type,"Missing approved definition consumer");var p=Packet();var snapshot=RunRiskBindingTests.Call(type,"Read",p,(string)p["packetHash"]);Assert.IsTrue(JToken.DeepEquals(p,(JObject)RunRiskBindingTests.Call(snapshot,"Capture")));}
  [Test] public void OriginalSyntheticNodeReceiptRestoresWithoutNewGenerator(){var type=typeof(RunWaveManifestSnapshot).Assembly.GetType("LastRail.Run.BScoutGunnerNodeSnapshot");Assert.NotNull(type,"Missing original source consumer");foreach(int i in new[]{0,1,2}){var p=Sample(i);var snapshot=RunRiskBindingTests.Call(type,"Read",p,Trust(p));Assert.IsTrue(JToken.DeepEquals(p,(JObject)RunRiskBindingTests.Call(snapshot,"Capture")));}}
  [Test] public void CadenceRoundsOriginalIntervalOnceBeforeMultiplyingGroup(){var timing=BScoutGunnerTiming.EntryAtClock("V",1,3000,3);Assert.AreEqual("429",timing.IntervalTicks.ToString());Assert.AreEqual("1287",timing.EntryNotBeforeTicks.ToString());Assert.AreEqual("3861000",timing.EntryNotBeforeMicroseconds.ToString());Assert.AreEqual("1286",((18000000L*3+14*3000-1)/(14*3000)).ToString());}
  [TestCase("I",1,600)][TestCase("II",1,546)][TestCase("III",5,417)][TestCase("IV",9,308)][TestCase("V",9,286)]
  public void ApprovedRiskCadenceExactClockBoundaries(string risk,int depth,int ticks){var timing=BScoutGunnerTiming.EntryAtClock(risk,depth,3000,1);Assert.AreEqual(ticks.ToString(),timing.IntervalTicks.ToString());}
  [TestCase(0,1)][TestCase(6000,250)][TestCase(12000,500)][TestCase(24000,1000)]
  public void FlightUsesRealMillimetersAndAtLeastOneOriginalTick(int millimeters,int ticks){Assert.AreEqual(ticks.ToString(),BScoutGunnerTiming.GunnerFlightAtClock(millimeters,1000).IntervalTicks.ToString());}
  [Test] public void SourceAndDefinitionCapturesCannotMutateVerifiedTypes(){var p=Sample(0);var s=BScoutGunnerNodeSnapshot.Read(p,Trust(p));var first=s.Waves[0].Instances[0];s.Capture()["waves"][0]["instances"][0]["hp"]="999";p["nativeContextId"]="other";Assert.AreEqual(first.Hp.ToString(),(string)s.Capture()["waves"][0]["instances"][0]["hp"]);var d=BScoutGunnerDefinitionSnapshot.Read(Packet(),BScoutGunnerDefinitionSnapshot.ApprovedPacketHash);Assert.AreEqual("24",(string)d.Types[0].RawAction.Snapshot()["numerator"]);Assert.AreEqual("20",(string)d.Types[1].RawAction.Snapshot()["numerator"]);Assert.IsFalse(d.CanStart);Assert.IsFalse(d.RuntimeSupported);d.Types[0].Capture()["basicPeriodMs"]=1;Assert.AreEqual(1600,d.Types[0].BasicPeriodMilliseconds);}
  [Test] public void MissingAuthenticatedDefinitionConsumerHasExplicitBoundary(){var type=typeof(RunWaveManifestSnapshot).Assembly.GetType("LastRail.Run.BScoutGunnerDefinitionClient");Assert.NotNull(type,"Missing original authenticated definition GET");}
  static void HashField(JObject p,string field){p.Remove(field);p[field]=LastRail.Battle.BDirectAttackInput.Digest(p).Substring(7);}
  static void Rehash(JObject p){foreach(JObject w in (JArray)p["waves"])HashField(w,"generationHash");var first=p["waves"][0];p["waves"][1]["previousComposition"]["generationHash"]=first["generationHash"].DeepClone();HashField((JObject)p["waves"][1],"generationHash");HashField(p,"sourceHash");}
  [TestCase("nativeContextId")][TestCase("seedHash")][TestCase("sourceHash")][TestCase("nodeId")][TestCase("visitDepth")][TestCase("priorSourceHash")]
  public void OriginalReceiptRequiresIndependentOwnerAnchors(string field){var p=Sample(1);var t=Trust(p);t[field]=field=="visitDepth"?new JValue(9):new JValue(field.EndsWith("Hash")?new string('f',64):"other");Assert.Throws<ArgumentException>(()=>BScoutGunnerNodeSnapshot.Read(p,t));}
  [TestCase("count")][TestCase("gunnerCount")][TestCase("ticket")][TestCase("shuffle")][TestCase("previous")][TestCase("hp")][TestCase("exactEhp")][TestCase("ehp")][TestCase("remainder")][TestCase("entry")][TestCase("type")][TestCase("riskFlag")][TestCase("support")][TestCase("version")][TestCase("extra")]
  public void RehashedReceiptStillRejectsInvalidCompositionAndAllocation(string fault){var p=Sample(0);var w=(JObject)p["waves"][0];var x=(JObject)w["instances"][0];switch(fault){case "count":w["count"]=16;break;case "gunnerCount":w["gunnerCount"]=0;break;case "ticket":w["rng"]["compositionTicket"]="99999999999999999999999999999999";break;case "shuffle":w["rng"]["shuffleChoices"][0]=99;break;case "previous":w["previousComposition"]=p["waves"][1]["previousComposition"].DeepClone();break;case "hp":x["hp"]="1";break;case "exactEhp":x["exactEhp"]["numerator"]="1";break;case "ehp":x["ehp"]="1";break;case "remainder":x["remainderUnitApplied"]=!(bool)x["remainderUnitApplied"];break;case "entry":x["entryNotBeforeUs"]["numerator"]="1";break;case "type":x["definitionRef"]["definitionId"]="enemy_old_a";break;case "riskFlag":x["hpRiskAppliedVersion"]="old";break;case "support":p["canStart"]=true;break;case "version":p["version"]="old";break;case "extra":p["privateSeed"]="client";break;}Rehash(p);Assert.Throws<ArgumentException>(()=>BScoutGunnerNodeSnapshot.Read(p,Trust(p)));}
  [Test] public void OwnerRestoreFailurePreservesAcceptedOriginalAndInvalidationClears(){var p=Sample(0);var owner=new BScoutGunnerNodeOwner();owner.RestoreVerified(p,Trust(p));var original=owner.Snapshot;var t=Trust(p);t["sourceHash"]=new string('f',64);Assert.Throws<ArgumentException>(()=>owner.RestoreVerified(p,t));Assert.AreSame(original,owner.Snapshot);owner.RestoreVerified(Sample(1),Trust(Sample(1)));Assert.AreEqual(5,owner.Snapshot.VisitDepth);owner.Invalidate();Assert.IsNull(owner.Snapshot);}
  static RunApiHttpResponse Response(JObject p)=>RunApiHttpResponse.Success(200,p.ToString(),new[]{new RunApiHttpHeader("Cache-Control","no-store"),new RunApiHttpHeader("ETag",(string)p["packetHash"])});
  [Test] public async Task BearerDefinitionReadAndRejectedRestoreRetainVerifiedSnapshot(){var p=Packet();var owner=RunRiskBindingTests.Session();var wire=new RunRiskBindingTests.Wire{Reply=r=>Task.FromResult(Response(p))};using var c=new BScoutGunnerDefinitionClient(new GameApiAuthenticatedHttpTransport(wire),()=>owner,()=>1);await c.RefreshAsync(BScoutGunnerDefinitionSnapshot.ApprovedPacketHash);Assert.NotNull(c.Snapshot);Assert.AreEqual("/v1/combat/b-scout-gunner-definition",wire.Last.EndpointPath);Assert.AreEqual("GET",wire.Last.Method);Assert.IsNull(wire.Last.BodyJson);Assert.IsTrue(wire.Last.Headers.Any(h=>h.Name=="Authorization"&&h.Value=="Bearer lst1.fixture"));Assert.IsTrue(wire.Last.Headers.Any(h=>h.Name=="X-Combat-B-Scout-Gunner-Version"&&h.Value==BScoutGunnerDefinitionSnapshot.Version));var original=c.Snapshot;var bad=(JObject)p.DeepClone();bad["definition"]["boarding"]=1000;HashField((JObject)bad["definition"],"definitionHash");HashField(bad,"packetHash");Assert.Throws<ArgumentException>(()=>c.RestoreVerified(bad,(string)bad["packetHash"]));Assert.AreSame(original,c.Snapshot);wire.Reply=r=>Task.FromResult(Response(bad));await c.RefreshAsync(BScoutGunnerDefinitionSnapshot.ApprovedPacketHash);Assert.AreEqual("CONTRACT_MISMATCH",c.Status);Assert.AreSame(original,c.Snapshot);}
  [Test] public async Task DefinitionRestoreAndDisposalSupersedeBorrowedPendingWait(){var p=Packet();var owner=RunRiskBindingTests.Session();var pending=new TaskCompletionSource<RunApiHttpResponse>();var wire=new RunRiskBindingTests.Wire{Reply=r=>pending.Task};var c=new BScoutGunnerDefinitionClient(new GameApiAuthenticatedHttpTransport(wire),()=>owner,()=>1);var task=c.RefreshAsync(BScoutGunnerDefinitionSnapshot.ApprovedPacketHash);c.RestoreVerified(p,BScoutGunnerDefinitionSnapshot.ApprovedPacketHash);Assert.AreSame(task,await Task.WhenAny(task,Task.Delay(200)));await task;pending.SetResult(RunApiHttpResponse.Success(409,"{\"errorCode\":\"combat_b_scout_gunner_stale\"}"));Assert.AreEqual("READY",c.Status);pending=new TaskCompletionSource<RunApiHttpResponse>();task=c.RefreshAsync(BScoutGunnerDefinitionSnapshot.ApprovedPacketHash);c.Dispose();Assert.AreSame(task,await Task.WhenAny(task,Task.Delay(200)));await task;pending.SetResult(Response(p));Assert.IsNull(c.Snapshot);}
 }
}
#endif
